diff --git a/app/build.gradle.kts b/app/build.gradle.kts
index 375447c19..32490d2a9 100644
--- a/app/build.gradle.kts
+++ b/app/build.gradle.kts
@@ -346,7 +346,8 @@ android {

     packaging {
         dex {
-            useLegacyPackaging = true
+            // Keep DEX directly mappable on API 29+ instead of inflating it during cold starts.
+            useLegacyPackaging = false
         }
         jniLibs {
             useLegacyPackaging = true
diff --git a/app/src/main/java/cn/com/omnimind/bot/activity/LauncherActivity.kt b/app/src/main/java/cn/com/omnimind/bot/activity/LauncherActivity.kt
index f25800aa5..081e1dbd4 100644
--- a/app/src/main/java/cn/com/omnimind/bot/activity/LauncherActivity.kt
+++ b/app/src/main/java/cn/com/omnimind/bot/activity/LauncherActivity.kt
@@ -62,16 +62,9 @@ class LauncherActivity : ComponentActivity() {
         }
         OmniLog.d(TAG, "startMainActivity")
         startActivity(intent)
-        // 不调用 finish()，让 MainActivity 的 Flutter 页面自然覆盖 Loading
-        // LauncherActivity 会在 MainActivity 渲染完成后被系统回收
-    }
-
-    override fun onStop() {
-        super.onStop()
-        // 当 MainActivity 覆盖 LauncherActivity 后，finish 自己
-        if (!isFinishing) {
-            OmniLog.d(TAG, "LauncherActivity onStop, finishing")
-            finish()
-        }
+        // This activity only routes intents and never draws content. Finish
+        // before onResume so the starting window can transfer to MainActivity
+        // without displaying an intermediate launcher window.
+        finish()
     }
 }
diff --git a/app/src/main/java/cn/com/omnimind/bot/activity/MainActivity.kt b/app/src/main/java/cn/com/omnimind/bot/activity/MainActivity.kt
index 13f0b98cb..21963c714 100644
--- a/app/src/main/java/cn/com/omnimind/bot/activity/MainActivity.kt
+++ b/app/src/main/java/cn/com/omnimind/bot/activity/MainActivity.kt
@@ -57,6 +57,11 @@ class MainActivity : FlutterActivity() {
         applyResponsiveOrientation()
         applySoftInputResizeMode()
         super.onCreate(savedInstanceState)
+        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
+            // Flutter's pre-draw gate keeps the splash until its first frame.
+            // Reveal that frame immediately instead of playing another exit animation.
+            splashScreen.setOnExitAnimationListener { splashView -> splashView.remove() }
+        }
         applyEdgeToEdgeWindow()
         TaskRuntimeSettings.attachActivity(this)
         TaskRuntimeSettings.consumeTaskCompletionNotificationIntent(this, intent)

benchmark_init_script:
// Measurement only. Keep the production release signing configuration untouched.
gradle.beforeProject { p ->
    p.plugins.withId('com.android.application') {
        if (p.path == ':app') {
            p.extensions.getByName('androidComponents').finalizeDsl { android ->
                def profile = android.buildTypes.maybeCreate('profile')
                profile.initWith(android.buildTypes.getByName('debug'))
                profile.matchingFallbacks = ['debug']
                profile.debuggable = true
                profile.minifyEnabled = false
                profile.shrinkResources = false
                android.buildTypes.getByName('release').signingConfig = android.signingConfigs.getByName('debug')
            }
        }
    }
}
